ee:message.ee:set-payload:
%dw 2.0
output application/json
var Preguntas = payload.Envelope.Body.ObtenerCuestionarioResponse.ObtenerCuestionarioResult.Cuestionario.*Pregunta
var Resultado = payload.Envelope.Body.ObtenerCuestionarioResponse.ObtenerCuestionarioResult
---
cuestionario: {
	id: Resultado.IdCuestionario,
	resultado: Resultado.ResultadoProceso,
	preguntas: (Preguntas map ((itemp, i) -> 
                        {
		pregunta: itemp.DescripcionPregunta,
		(respuestas: itemp.Respuestas.*string map ((itemr, j) -> {
			texto: itemr
		}))
	}
                    )),
}

%dw 2.0
output application/json
---
{
    "Identificador_Peticion": correlationId default ("MDM-LISIM-CUESTIONARIO-" ++ (vars.cuestionarioQueryParams.TipoIdentificacion default "9") ++ "-" ++ (vars.cuestionarioQueryParams.Identificacion default "")),
    "Tipo_Documento": vars.cuestionarioQueryParams.TipoIdentificacion default "9",
    "Numero_Identificacion": (vars.cuestionarioQueryParams.Identificacion default "") as Number,
    "Numero_Conexion": "",
    "Tipo_Transaccion": "Registro Log LISIM",
    Fecha_Inicio: now() >> "America/Bogota",
    Fecha_Fin: now() >> "America/Bogota",
    Estado_Transaccion: "",
    Sistema_Origen: "MULESOFT",
    Atributos: [
      {
        name: "FECHA_CONSULTA",
        value: now() as DateTime{format: "dd/MM/yyyy"}
      },
      {
        name: "HORA_CONSULTA",
        value: now() as DateTime{format: "HH:mm"}
      },
      {
        name: "TIPO_IDENTIFICACION",
        value: vars.cuestionarioQueryParams.TipoIdentificacion default ""
      },
      {
        name: "NUMERO_IDENTIFICACION",
        value: vars.cuestionarioQueryParams.Identificacion default ""
      },
      {
        name: "APELLIDO",
        value: vars.cuestionarioQueryParams.Apellido default ""
      },
      {
        name: "NOMBRE",
        value: vars.cuestionarioQueryParams.Nombre default ""
      },
      {
        name: "TRAMITE",
        value: vars.cuestionarioQueryParams.Tramite default ""
      },
      {
        name: "TIPO_CONSULTA",
        value: vars.cuestionarioQueryParams.Tipo_Consulta default "SOLICITUD PREGUNTAS CONFRONTA"
      },
      {
        name: "USUARIO",
        value: vars.cuestionarioQueryParams.Usuario default ""
      },
      {
        name: "CANAL",
        value: vars.cuestionarioQueryParams.CanalVenta default ""
      },
      {
        name: "PROVEEDOR",
        value: vars.cuestionarioQueryParams.Proveedor default ""
      },
      {
        name: "CIUDAD",
        value: vars.cuestionarioQueryParams.Ciudad as String default ""
      },
      {
        name: "DEPARTAMENTO",
        value: vars.cuestionarioQueryParams.Departamento as String default ""
      },
      {
        name: "ESTADO_ETB",
        value: "CONSULTA EXITOSA"
      },
      {
        name: "SISTEMA_ORIGEN",
        value: vars.cuestionarioQueryParams.Sistema_Origen default "MiETB"
      },
      {
        name: "MENSAJE",
        value: write(payload,"application/json", indent:false), 
      },
      {
        name: "NIVEL_RIESGO",
        value: vars.cuestionarioQueryParams.NivelRiesgo default ""
      },
      {
        name: "SCORE",
        value: vars.cuestionarioQueryParams.Score default ""
      },
      {
        name: "ID",
        value: correlationId
      },
      {
        name: "MODELO",
        value: vars.cuestionarioQueryParams.Modelo default ""
      },
      {
        name: "PORTAL",
        value: vars.cuestionarioQueryParams.Portal default ""
      },
      {
        name: "NUMERO_CONTACTO",
        value: vars.cuestionarioQueryParams.Numero_Contacto default ""
      },
      {
        name: "TIPO",
        value: vars.cuestionarioQueryParams.Tipo default ""
      },
      {
        name: "ESTRATO",
        value: vars.cuestionarioQueryParams.Estrato default ""
      }
      ]
  }
